"use strict";dotclear.ready(()=>{const e=document.getElementById("hscroll-bar");if(!e)return;const l=e.classList.contains("vertical"),t=()=>{const t=globalThis.scrollY/(document.body.clientHeight-globalThis.innerHeight)*100+"%";l?e.style.blockSize=t:e.style.inlineSize=t};globalThis.addEventListener("load",t),globalThis.addEventListener("scroll",t),t()});
